      `<div class="muted" style="font-size:13px">反応◎</div><div style="display:flex;flex-wrap:wrap;gap:6px;margin:6px 0">${gl.map(x=>`<span style="display:inline-flex;align-items:center;font-size:14px;padding:3px 2px 3px 10px;border:1px solid var(--line);border-radius:999px">${esc(snm2(x.staff_id))}<span style="color:var(--gold)">◎</span><button data-bpg="${x.id}" style="border:0;background:none;min-height:0;padding:0 8px;color:var(--muted)">×</button></span>`).join('')}${sel('g','＋反応◎',staffAll.filter(s=>s.is_active&&s.kind==='cast'&&!s.kakari_only&&att.has(s.id)&&!gl.some(x=>x.staff_id===s.id)))}</div>`;
